def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "reach_into_cabinet": And([
            Not(self.cabinet_scanned),
            Not(self.cabinet_closed),
            self.cabinet_has_sharp_objects,
            self.robot_has_gripper
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
